from survival.yates_setup import yates_setup
import numpy as np
from scipy.special import expit

fit = {"class": ["coxph"]}
gfit = {"class": ["glm", "lm"], "family": {"linkinv": expit}}
eta = np.array([-1.0, 0.0, 1.0])
print(yates_setup(fit) is None)
for v in yates_setup(fit, predict="risk")(eta, None):
    print(f"{v:.17g}")
for v in yates_setup(gfit, predict="response")(eta, None):
    print(f"{v:.17g}")
